#!/usr/bin/env bash
#
# push_to_github.sh — commit changes on a NEW branch, push it, and open a PR
# so you can review & merge it yourself on GitHub.
#
# Usage:
#   ./push_to_github.sh [REPO_DIR] [COMMIT_MESSAGE] [BRANCH_NAME]
#
#   REPO_DIR       Path to your local codebase (default: current directory)
#   COMMIT_MESSAGE Commit message (default: auto-generated with timestamp)
#   BRANCH_NAME    Branch to create & push (default: update/YYYYMMDD-HHMMSS)
#
# Examples:
#   ./push_to_github.sh ~/Desktop/deep\ learning "ex00 done"
#   ./push_to_github.sh . "week 2" feature/week-2
#
# Optional env vars:
#   REMOTE_URL  Override the SSH remote (default: Piscine-Deep-Learning repo)
#   BASE_BRANCH PR hedefi (default: main)

set -euo pipefail

REMOTE_URL="${REMOTE_URL:-git@github.com:atalayerdgn/Piscine-Deep-Learning.git}"
BASE_BRANCH="${BASE_BRANCH:-main}"
REPO_DIR="${1:-.}"
COMMIT_MSG="${2:-Update codebase - $(date '+%Y-%m-%d %H:%M:%S')}"
BRANCH="${3:-update/$(date '+%Y%m%d-%H%M%S')}"

# --- Pre-flight checks -------------------------------------------------------

if ! command -v git >/dev/null 2>&1; then
    echo "ERROR: git is not installed or not in PATH." >&2
    exit 1
fi

if [ ! -d "$REPO_DIR" ]; then
    echo "ERROR: directory '$REPO_DIR' does not exist." >&2
    exit 1
fi

cd "$REPO_DIR"
echo "==> Working in: $(pwd)"

# --- Init repo if needed ------------------------------------------------------

if [ ! -d .git ]; then
    echo "==> No git repo found — running 'git init'..."
    git init
    git branch -M "$BASE_BRANCH"
fi

# --- Configure remote ---------------------------------------------------------

if git remote get-url origin >/dev/null 2>&1; then
    current_url="$(git remote get-url origin)"
    if [ "$current_url" != "$REMOTE_URL" ]; then
        echo "==> Remote 'origin' points to '$current_url' — updating to '$REMOTE_URL'"
        git remote set-url origin "$REMOTE_URL"
    else
        echo "==> Remote 'origin' already correct."
    fi
else
    echo "==> Adding remote 'origin' -> $REMOTE_URL"
    git remote add origin "$REMOTE_URL"
fi

# --- Make sure the base branch exists locally ---------------------------------

if ! git rev-parse --verify "$BASE_BRANCH" >/dev/null 2>&1; then
    echo "==> No local '$BASE_BRANCH' — fetching from origin..."
    git fetch origin "$BASE_BRANCH" 2>/dev/null && git branch "$BASE_BRANCH" "origin/$BASE_BRANCH" \
        || { echo "ERROR: '$BASE_BRANCH' not found locally or on remote." >&2; exit 1; }
fi

# --- Create the feature branch ------------------------------------------------

if git rev-parse --verify "$BRANCH" >/dev/null 2>&1; then
    echo "==> Branch '$BRANCH' already exists — checking it out."
    git checkout "$BRANCH"
else
    echo "==> Creating branch '$BRANCH' from '$BASE_BRANCH'..."
    git checkout -b "$BRANCH" "$BASE_BRANCH"
fi

# --- Stage and commit ----------------------------------------------------------

git add -A

if git diff --cached --quiet; then
    echo "==> Nothing new to commit on this branch."
    # If the branch was just created with no commits, there's nothing to push
    if ! git rev-parse --verify HEAD >/dev/null 2>&1; then
        echo "ERROR: no commits at all — nothing to open a PR with." >&2
        exit 1
    fi
else
    echo "==> Committing changes..."
    git commit -m "$COMMIT_MSG"
fi

# --- Push the branch -----------------------------------------------------------

echo "==> Pushing branch '$BRANCH'..."
git push -u origin "$BRANCH"

# --- Open (or link to) the PR ---------------------------------------------------

PR_TITLE="$COMMIT_MSG"
HTTPS_URL="$(echo "$REMOTE_URL" | sed -E 's#^git@github\.com:#https://github.com/#; s#\.git$##')"
COMPARE_URL="$HTTPS_URL/compare/$BASE_BRANCH...$BRANCH?expand=1"

if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    echo "==> Creating pull request via GitHub CLI..."
    gh pr create --base "$BASE_BRANCH" --head "$BRANCH" \
        --title "$PR_TITLE" \
        --body "Auto-generated by push_to_github.sh"
else
    echo "==> 'gh' CLI not available/authed — open the PR manually:"
    echo "    $COMPARE_URL"
fi

echo "==> Done. Branch: $BRANCH -> PR base: $BASE_BRANCH"
